.ds-input,.ds-select,.ds-check,.ds-details{font-family:var(--font-ui);font-size:14px;color:var(--color-ink)}.ds-input:focus-visible,.ds-select:focus-visible,.ds-check:focus-visible,.ds-details summary:focus-visible{outline:3px solid var(--color-focus);outline-offset:3px}.ds-input,
.ds-textarea,
.ds-select {
  border: 1px solid var(--color-line);
  border-radius: var(--radius-control);
  background: var(--color-surface);
  color: inherit;
  padding: 9px 12px;
  min-width: 0;
  min-height: 40px;
  font-weight: 400;
  transition:
    border-color var(--duration-feedback),
    background var(--duration-feedback);
}
:is(.ds-input, .ds-textarea, .ds-select):hover:not(:disabled) {
  border-color: var(--color-control-line);
}
:is(.ds-input, .ds-textarea, .ds-select):focus-visible {
  border-color: var(--color-focus);
  outline: 2px solid var(--color-selected);
  outline-offset: 1px;
}
:is(.ds-input, .ds-textarea, .ds-select):disabled {
  background: var(--color-subtle);
  color: var(--color-muted);
  cursor: not-allowed;
}
:is(.ds-input, .ds-textarea, .ds-select)[aria-invalid="true"] {
  border-color: var(--color-danger);
}
.ds-input{caret-color:var(--color-accent)}.ds-input::placeholder{color:var(--color-muted);opacity:1}@media(prefers-reduced-motion:reduce){.ds-input,.ds-select,.ds-select::picker-icon,.ds-check,.ds-details summary,.ds-details summary::after{transition:none}}

